1	use schemars::JsonSchema;
2	use serde::{Deserialize, Deserializer, Serialize, Serializer};
3	
4	use crate::identity::string_json_schema;
5	use crate::Ecosystem;
6	
7	/// `SemVer` is the only implemented grammar; the rest are declared so `Ecosystem::version_grammar` is total.
8	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
9	#[serde(rename_all = "camelCase")]
10	#[non_exhaustive]
11	pub enum VersionGrammar {
12	    SemVer,
13	    /// PEP 440 — declared, not implemented.
14	    Pep440,
15	    /// Maven's qualifier-ordering comparator — declared, not implemented.
16	    Maven,
17	}
18	
19	/// The parsed form, kept alongside `raw` so comparison and component access are cheap.
20	#[derive(Clone, Debug, PartialEq, Eq, Hash)]
21	pub(crate) enum ParsedVersion {
22	    SemVer(semver::Version),
23	    Pep440(pep440_rs::Version),
24	}
25	
26	/// A parsed version, tagged with the grammar it was parsed under.
27	#[derive(Clone, Debug, PartialEq, Eq, Hash)]
28	pub struct Version {
29	    pub(crate) grammar: VersionGrammar,
30	    pub(crate) raw: String,
31	    pub(crate) parsed: ParsedVersion,
32	}
33	
34	string_json_schema!(Version);
35	
36	impl Version {
37	    /// Parses a native version using its owning distribution's ecosystem.
38	    pub fn parse_for_ecosystem(raw: &str, ecosystem: Ecosystem) -> Result<Self, VersionParseError> {
39	        Self::parse(raw, ecosystem.version_grammar())
40	    }
41	
42	    pub fn parse(raw: &str, grammar: VersionGrammar) -> Result<Self, VersionParseError> {
43	        match grammar {
44	            VersionGrammar::SemVer => {
45	                let parsed = semver::Version::parse(raw).map_err(|e| VersionParseError {
46	                    raw: raw.to_string(),
47	                    grammar,
48	                    message: e.to_string(),
49	                })?;
50	                Ok(Version {
51	                    grammar,
52	                    raw: raw.to_string(),
53	                    parsed: ParsedVersion::SemVer(parsed),
54	                })
55	            }
56	            VersionGrammar::Pep440 => {
57	                let parsed = raw.parse::<pep440_rs::Version>().map_err(|e| VersionParseError {
58	                    raw: raw.to_string(),
59	                    grammar,
60	                    message: e.to_string(),
61	                })?;
62	                // PEP 440 defines multiple equivalent spellings for the same
63	                // version (e.g. `1.0.0-alpha1`, `1.0.0_alpha1`, `1.0.0a1`).
64	                // Normalize `raw` to pep440_rs's canonical rendering so that
65	                // logically-equal inputs produce identical `raw` values, and
66	                // therefore compare `==` and hash equal (derived PartialEq/Eq/
67	                // Hash include `raw`). SemVer has no analogous normalization
68	                // requirement (each version already has one canonical form),
69	                // so the caller's literal input is preserved for that grammar.
70	                let canonical = parsed.to_string();
71	                Ok(Version {
72	                    grammar,
73	                    raw: canonical,
74	                    parsed: ParsedVersion::Pep440(parsed),
75	                })
76	            }
77	            VersionGrammar::Maven => Err(VersionParseError {
78	                raw: raw.to_string(),
79	                grammar,
80	                message: format!("{grammar:?} has no versioning implementation yet"),
81	            }),
82	        }
83	    }
84	
85	    pub fn semver(major: u64, minor: u64, patch: u64) -> Self {
86	        let parsed = semver::Version::new(major, minor, patch);
87	        Version {
88	            grammar: VersionGrammar::SemVer,
89	            raw: parsed.to_string(),
90	            parsed: ParsedVersion::SemVer(parsed),
91	        }
92	    }
93	
94	    pub fn grammar(&self) -> VersionGrammar {
95	        self.grammar
96	    }
97	
98	    pub fn render(&self) -> &str {
99	        &self.raw
100	    }
101	
102	    pub fn raw(&self) -> &str {
103	        &self.raw
104	    }
105	
106	    pub fn major(&self) -> Option<u64> {
107	        match &self.parsed {
108	            ParsedVersion::SemVer(v) => Some(v.major),
109	            ParsedVersion::Pep440(v) => v.release().first().copied(),
110	        }
111	    }
112	
113	    pub fn minor(&self) -> Option<u64> {
114	        match &self.parsed {
115	            ParsedVersion::SemVer(v) => Some(v.minor),
116	            ParsedVersion::Pep440(v) => v.release().get(1).copied(),
117	        }
118	    }
119	
120	    pub fn patch(&self) -> Option<u64> {
121	        match &self.parsed {
122	            ParsedVersion::SemVer(v) => Some(v.patch),
123	            ParsedVersion::Pep440(v) => v.release().get(2).copied(),
124	        }
125	    }
126	
127	    pub fn is_prerelease(&self) -> bool {
128	        match &self.parsed {
129	            ParsedVersion::SemVer(v) => !v.pre.is_empty(),
130	            ParsedVersion::Pep440(v) => !v.is_post() && (v.is_pre() || v.is_dev()),
131	        }
132	    }
133	
134	    pub fn compare(&self, other: &Version) -> Result<std::cmp::Ordering, GrammarMismatch> {
135	        if self.grammar != other.grammar {
136	            return Err(GrammarMismatch {
137	                left: self.grammar,
138	                right: other.grammar,
139	            });
140	        }
141	        match (&self.parsed, &other.parsed) {
142	            (ParsedVersion::SemVer(a), ParsedVersion::SemVer(b)) => Ok(a.cmp(b)),
143	            (ParsedVersion::Pep440(a), ParsedVersion::Pep440(b)) => Ok(a.cmp(b)),
144	            _ => unreachable!(),
145	        }
146	    }
147	
148	    pub fn partial_compare(&self, other: &Version) -> Option<std::cmp::Ordering> {
149	        self.compare(other).ok()
150	    }
151	}
152	
153	impl std::fmt::Display for Version {
154	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
155	        write!(f, "{}", self.raw)
156	    }
157	}
158	
159	impl Serialize for Version {
160	    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
161	    where
