/// Package identity extracted directly from manifest source text via
/// [`read_identity`], without going through the full `Manifest::open`
/// lifecycle (workspace-inheritance context, on-disk path resolution,
/// atomic-write machinery). For callers that already hold a manifest's
/// content as a string -- a `git show` blob, a walker's pre-read buffer --
/// and only need the package's name and/or where its version comes from.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ManifestIdentity {
    pub name: Option<String>,
    pub version: Option<VersionSource>,
}

/// Where a manifest's version declaration comes from. Distinct from a raw
/// `Option<String>` so Cargo's `version.workspace = true` is a real,
/// distinguishable case instead of being silently collapsed into "no
/// version present". [`read_identity`] never resolves the inherited value
/// (it has no workspace context); [`read_effective_version`] resolves supplied blobs.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum VersionSource {
    Literal(String),
    InheritedFromWorkspace,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct EffectiveManifestVersion {
    pub version: Version,
    pub authority: std::path::PathBuf,
}

/// Reads a manifest's effective version from text the caller already holds. `manifest_at` supplies any other
/// workspace-relative manifest by path, or `None` when there is none, so a Cargo `version.workspace = true` resolves
/// against the workspace that governs the package at the same revision. `reads` remembers the workspace manifests
/// already seen, so reading many packages of one revision parses each once.
///
/// # Errors
///
/// The manifest does not parse, declares an invalid version, or inherits one that no governing workspace declares; or
/// `manifest_at` fails.
pub fn read_effective_version<E: From<ManifestError>>(
    format: ManifestFormat,
    source: &str,
    path: &Path,
    reads: &mut WorkspaceReads,
    mut manifest_at: impl FnMut(&Path) -> Result<Option<String>, E>,
) -> Result<Option<EffectiveManifestVersion>, E> {
    let identity = read_identity(format, source, path)?;
    let (version, authority) = match identity.version {
        Some(VersionSource::Literal(raw)) => {
            let version = Version::parse(&raw, format.ecosystem().version_grammar()).map_err(|source| {
                ManifestError::InvalidVersion {
                    path: path.to_path_buf(),
                    raw,
                    source,
                }
            })?;
            (version, path.to_path_buf())
        }
        Some(VersionSource::InheritedFromWorkspace) => {
            let missing = |path: &Path| ManifestError::MissingField {
                path: path.to_path_buf(),
                field: "workspace.package.version",
            };
            let member = cargo::parse_manifest(path, source)?;
            let root_manifest = reads
                .enclosing(path, &member, &mut manifest_at)?
                .ok_or_else(|| missing(path))?;
            let version = reads
                .version(&root_manifest, &mut manifest_at)?
                .ok_or_else(|| missing(&root_manifest))?;
            (version, root_manifest)
        }
        None => return Ok(None),
    };
    Ok(Some(EffectiveManifestVersion { version, authority }))
}

/// Extracts a package's name and version source directly from `source`,
/// the raw text of a manifest matching `format`. Pure and I/O-free.
///
/// Replaces hand-parsing `Cargo.toml`/`package.json`/`pyproject.toml` at
/// call sites that already hold manifest content as a string rather than a
/// path `open()` can read from disk (audit pattern B) -- e.g. a `git show`
/// blob, or a directory-walker's pre-read buffer.
///
/// `path` is used only to build accurate `ManifestError::Parse` locations
/// on a parse failure; it need not exist on disk. Only the three
/// canonical-identity formats ([`Ecosystem::CANONICAL`]) are supported --
/// any other format returns `Err(ManifestError::ReadOnlyFormat)`.
pub fn read_identity(format: ManifestFormat, source: &str, path: &Path) -> Result<ManifestIdentity, ManifestError> {
    match format {
        ManifestFormat::CargoToml => cargo::identity_from_source(source, path),
        ManifestFormat::PackageJson => npm::identity_from_source(source, path),
        ManifestFormat::PyprojectToml => python::identity_from_source(source, path),
        other => Err(ManifestError::ReadOnlyFormat {
            path: path.to_path_buf(),
            format: other,
            reason: "read_identity only supports the three canonical-identity manifest formats \
                     (Cargo.toml, package.json, pyproject.toml)",
        }),
    }
}

/// The role an npm `package.json` manifest's own content declares itself to
/// play (e.g. a napi-rs platform package, signaled by `os`+`cpu` constraint
/// arrays), detected directly from the manifest's already-parsed document.
///
/// Distinct from [`ManifestRole`], which reflects the role a [`ManifestDecl`]
/// was *opened with* (assigned externally by the caller), not what the
        })
}

/// [`crate::read_identity`]'s `pyproject.toml` implementation: parses
/// `source` and extracts a package name (PEP 621, falling back to Poetry
/// then Flit -- see [`python_package_name`]) plus a
/// [`crate::VersionSource::Literal`] version (PEP 621 `project.version`,
/// falling back to Poetry's `tool.poetry.version`). Python has no
/// workspace-inherited-version concept analogous to Cargo's, and a Flit or
/// PEP 621 `dynamic = ["version"]` package has no static version to report
/// at all, so both fall through to `None`.
pub(crate) fn identity_from_source(source: &str, path: &Path) -> Result<crate::ManifestIdentity, ManifestError> {
    let clean = source.strip_prefix('\u{FEFF}').unwrap_or(source);
    let doc: toml_edit::DocumentMut = clean.parse().map_err(|e: toml_edit::TomlError| ManifestError::Parse {
        path: path.to_path_buf(),
        format: ManifestFormat::PyprojectToml,
        message: e.to_string(),
    })?;

    let name = python_package_name(&doc).map(str::to_string);
    let version = doc
        .get("project")
        .and_then(|p| p.get("version"))
        .and_then(|v| v.as_str())
        .or_else(|| {
            doc.get("tool")
                .and_then(|t| t.get("poetry"))
                .and_then(|p| p.get("version"))
                .and_then(|v| v.as_str())
        })
        .map(|s| crate::VersionSource::Literal(s.to_string()));

    Ok(crate::ManifestIdentity { name, version })
}

/// A parsed PEP 508 dependency specifier, e.g.
    }
    Ok(())
}

/// [`crate::read_identity`]'s `Cargo.toml` implementation: parses `source`
/// and extracts `[package].name` plus a [`crate::VersionSource`] for
/// `[package].version` -- `InheritedFromWorkspace` when it's
/// `version.workspace = true`, `Literal` when it's a bare string, `None`
/// when the field or the whole `[package]` table is absent.
pub(crate) fn identity_from_source(source: &str, path: &Path) -> Result<crate::ManifestIdentity, ManifestError> {
    let clean = source.strip_prefix('\u{FEFF}').unwrap_or(source);
    let doc: toml_edit::DocumentMut = clean.parse().map_err(|e: toml_edit::TomlError| ManifestError::Parse {
        path: path.to_path_buf(),
        format: ManifestFormat::CargoToml,
        message: e.to_string(),
    })?;

    let name = cargo_package_name(&doc).map(str::to_string);
    let version = doc.get("package").and_then(|p| p.get("version")).and_then(|v| {
        if let Some(s) = v.as_str() {
            Some(crate::VersionSource::Literal(s.to_string()))
        } else if v.get("workspace").and_then(|w| w.as_bool()) == Some(true) {
            Some(crate::VersionSource::InheritedFromWorkspace)
        } else {
            None
        }
    });

    Ok(crate::ManifestIdentity { name, version })
}

